#include <Arduino.h>
const int SHCP_PIN = A2;  
const int STCP_PIN = A1;  
const int DS_PIN = A0;    
const int RGB1_RED = 2;   
const int RGB1_GREEN = 3; 
const int RGB1_BLUE = 4;  
const int RGB2_RED = 5;   
const int RGB2_GREEN = 6; 
const int RGB2_BLUE = 7;  
const int POT1_PIN = A3;  
const int POT2_PIN = A4;  
const int POT3_PIN = A5;  
const byte segmentCodes[] = {
  0b11000000, 
  0b11111001, 
  0b10100100, 
  0b10110000, 
  0b10011001, 
  0b10010010, 
  0b10000010, 
  0b11111000, 
  0b10000000, 
  0b10010000  
};

void setup();
void loop();
void displayNumber(int tens, int ones);
void setup() {
  pinMode(SHCP_PIN, OUTPUT);
  pinMode(STCP_PIN, OUTPUT);
  pinMode(DS_PIN, OUTPUT);
  pinMode(RGB1_RED, OUTPUT);
  pinMode(RGB1_GREEN, OUTPUT);
  pinMode(RGB1_BLUE, OUTPUT);
  pinMode(RGB2_RED, OUTPUT);
  pinMode(RGB2_GREEN, OUTPUT);
  pinMode(RGB2_BLUE, OUTPUT);
}
void loop() {
  int redValue = map(analogRead(POT1_PIN), 0, 1023, 0, 255);
  int greenValue = map(analogRead(POT2_PIN), 0, 1023, 0, 255);
  int blueValue = map(analogRead(POT3_PIN), 0, 1023, 0, 255);
  int tens = map(redValue,0,255,0,9);
  int ones = map(blueValue,0,255,0,9);
  analogWrite(RGB1_RED, redValue);
  analogWrite(RGB1_GREEN, greenValue);
  analogWrite(RGB1_BLUE, blueValue);
  analogWrite(RGB2_RED, redValue);
  analogWrite(RGB2_GREEN, greenValue);
  analogWrite(RGB2_BLUE, blueValue);
  displayNumber(tens,ones);
}
void displayNumber(int tens, int ones) {
  byte tensCode = segmentCodes[tens];
  byte onesCode = segmentCodes[ones];
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, onesCode);
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, tensCode);
  digitalWrite(STCP_PIN, HIGH);
  digitalWrite(STCP_PIN, LOW);
}
